// A labeled visual preview generated by the same renderer shipped in the CLI.
import {fabricFrame} from '../npm/joinweave/src/terminal.js';
import {writeFileSync,mkdirSync} from 'node:fs';
import {resolve,join} from 'node:path';
const out=resolve(process.argv[2]);
mkdirSync(out,{recursive:true});
const frames=Array.from({length:72},(_,tick)=>fabricFrame(70,20,tick,Math.floor(tick/12),false).join('\n'));
writeFileSync(join(out,'installer-animation-preview.json'),JSON.stringify({
  version:'0.1.2',label:'Installer animation preview. Installation progress is illustrative.',
  columns:70,rows:20,frameMilliseconds:120,frames
})+'\n');
